-- =====================================================================
-- Import de Ordenes de Fabricacion (legacy `of`, 630 filas)
--
-- Mapeo directo: numero_of=id_of, tipo_orden_id resuelto por nombre
-- (FABRICACION/REPARACION, las unicas 2 que aparecen en la legacy de
-- las 4 que tiene ingenieria.tipos_orden), cliente_id=cliente (mismo
-- id que catalogo.clientes, ver 029_import_clientes.sql),
-- rubro_id=rubro_albion (matchea 1:1 contra catalogo.rubros, ya
-- confirmado: ningun valor fuera de 1-30), vendedor_id/creado_por
-- resueltos por username contra core.usuarios, estado_id=estado (ya
-- coincide 1:1 con ingenieria.estados_of: 1=NORMAL/2=FINALIZADA/3=DETENIDA).
--
-- layout_url/pautas_url quedan NULL: la legacy solo guarda el NOMBRE
-- de archivo (.doc/.pdf), no hay carpeta de esos archivos disponible
-- todavia -- no se inventa una URL que no existe. Si en algun momento
-- se copian esos archivos, se puede hacer un linkeo posterior igual
-- que se hizo con los PDF/DXF de maquinas.
--
-- estado_id: 26 filas con estado NULL en la legacy (las OF mas nuevas,
-- creadas y todavia sin marcar) -- estado_id es NOT NULL en el schema
-- nuevo, se usa 1=NORMAL como default (no es informacion inventada,
-- es el estado por defecto real que tenian el resto de las OF activas
-- sin marcar en la legacy).
--
-- cliente_id: la fila id_of=77 referencia cliente=628, que NO existe
-- en clientesalbion (era un id ya borrado o nunca migrado en la
-- legacy) -- queda cliente_id NULL en vez de inventar un cliente.
--
-- creado_por: 14 filas con usuario en blanco en la legacy -> NULL.
-- creado_en: no hay timestamp de creacion real en la legacy, se usa
-- la fecha de la OF (unico dato de fecha real disponible) a
-- medianoche Argentina -- evita que las 630 OF historicas aparezcan
-- como "nuevas" (creadas hoy) en el sistema.
-- =====================================================================

BEGIN;

DELETE FROM ingenieria.ordenes_trabajo WHERE numero_ot = 5001;
DELETE FROM ingenieria.ordenes_fabricacion WHERE numero_of = 3001;

INSERT INTO ingenieria.ordenes_fabricacion
    (numero_of, tipo_orden_id, cliente_id, fecha, fecha_entrega, rubro_id, referencia, nota, vendedor_id, estado_id, creado_por, creado_en)
